  @override
  String get legalDataConsentAuditBody =>
      'DVTech Ventures maintains an audit trail of all consent events (grant, modification, withdrawal), data flows into training pipelines, anonymization certifications, and third-party processor instructions. Tenant administrators can request a consent audit report via the governance settings dashboard. We conduct annual AI ethics and data governance reviews.';

