      'For questions about AI data processing, consent, or to request a copy of consent records: support@odaflow.com. We aim to respond within 10 business days.';

  @override
  String get legalDataConsentContactHeading =>
      '11. Contact for AI data enquiries';

  @override
  String get legalDataConsentCountryDPDPBody =>
      'India (DPDP Act 2023): processing of digital personal data for AI training requires explicit consent from the Data Principal. Consent records are maintained and can be reviewed or withdrawn via your account settings.';

  @override
  String get legalDataConsentCountryGDPRBody =>
      'EU / UK (GDPR / UK GDPR): automated processing that produces legal or similarly significant effects requires a valid legal basis under Art. 22 GDPR. Umbrella does not make binding automated decisions about users. Where AI analysis influences significant outcomes, users are notified and human review is available.';

  @override
  String get legalDataConsentCountryHeading =>
      '6. Country-specific requirements';

  @override
  String get legalDataConsentCountryKenyaBody =>
      'Kenya (Data Protection Act 2019): automated processing and profiling must be disclosed; data subjects have the right to object. Consent for any AI training use is obtained separately and documented.';

  @override
  String get legalDataConsentCountryUSBody =>
      'United States: CCPA/CPRA users have the right to opt out of the sale or sharing of personal information. Umbrella does not sell personal information. Sharing data with AI providers for service delivery is not a \'sale\' under CCPA. Sensitive personal information is not shared with AI providers without explicit consent.';

  @override
  String get legalDataConsentDefaultBody =>
      'By default, Umbrella does not use your documents, case descriptions, matter notes, client communications, AI queries, or any other user-submitted content to train, fine-tune, or evaluate AI models. This default applies to all users — consumers, Lawyer Users, and firm tenants — regardless of subscription tier. Firm training consent defaults to off for all tenants and can only be enabled by a tenant administrator.';

  @override
  String get legalDataConsentDefaultHeading =>
      '1. Default: no training on your data';

  @override
  String get legalDataConsentDescription =>
      'This policy explains how DVTech Ventures handles your data in relation to AI model training, evaluation, and improvement. It forms part of our overall Privacy Policy.';

  @override
  String get legalDataConsentFirmLink =>
      'Firm training consent (tenant admin — Lawyer OS settings)';

  @override
  String get legalDataConsentFormDefaultIs => 'Default is';

  @override
  String get legalDataConsentManageBody =>
      'Consent can be granted or withdrawn at any time via your account settings. Changes take effect immediately for future data processing. Withdrawal does not affect processing carried out before the withdrawal.';

  @override
  String get legalDataConsentManageHeading => '7. How to manage your consent';

  @override
  String get legalDataConsentNeverUsedBody =>
      'The following data is never used for AI training under any circumstances, including with opt-in: (a) billing information and payment card data; (b) full client names, national ID numbers, passport numbers, or biometric data without complete anonymization; (c) communications protected by legal professional privilege unless the privilege holder provides explicit written consent; (d) data subject to a legal hold or active litigation; (e) health or medical data; (f) data of users under 18 years of age.';

  @override
  String get legalDataConsentNeverUsedHeading =>
      '4. Data that is never used for training';

  @override
  String get legalDataConsentOptInAnonymize =>
      'All opt-in data undergoes anonymization (removal of personal identifiers) and pseudonymization (replacement of names, entities, and case references with synthetic tokens) before entering any training pipeline. Anonymization is verified by automated scanning and, for fine-tuning, manual spot-checks.';

  @override
  String get legalDataConsentOptInEval =>
      'Model evaluation: redacted samples from your AI interactions are used to test model quality, safety, and accuracy against benchmarks. Samples are reviewed only by authorised DVTech engineers and contracted AI evaluators under NDA.';

  @override
  String get legalDataConsentOptInFineTune =>
      'Fine-tuning: with admin approval, pseudonymized legal drafts or matter summaries may be included in fine-tuning datasets to improve domain-specific model performance. Fine-tuning datasets require dual-approval by a tenant admin and a DVTech data governance officer.';

  @override
  String get legalDataConsentOptInHeading => '3. What opt-in enables';

  @override
  String get legalDataConsentOptInIntro =>
      'If you choose to opt in, you may enable one or more of the following, each independently:';

  @override
  String get legalDataConsentOptInIntroSection =>
      'If you opt in, you may separately enable:';

  @override
  String get legalDataConsentOptInPrompt =>
      'Prompt improvement: anonymized patterns from your AI queries are used to improve prompt engineering and reduce hallucinations. No personally identifiable information or case-specific facts are included.';

  @override
  String get legalDataConsentProvidersBody =>
      'Umbrella routes AI queries to third-party AI providers. For analysis and drafting: OpenAI (GPT models) and DeepSeek. For embeddings and document search: OpenAI. For meeting and voice transcription: Deepgram. These providers process your queries under: (a) zero-data-retention API agreements where available (queries are not used to train provider models); (b) data processing agreements that restrict use to service delivery; (c) appropriate cross-border transfer mechanisms (SCCs for EU/UK; equivalent agreements for other jurisdictions). The specific providers in use for each feature are documented in our subprocessor register available on request.';

  @override
  String get legalDataConsentProvidersHeading => '5. Third-party AI providers';

  @override
  String get legalDataConsentRetentionBody =>
      'Anonymized training datasets are retained for the period necessary for model development, typically 24 months from creation. Fine-tuning datasets require explicit re-consent after 12 months. Upon tenant account closure, all training data derived from that tenant\'s content is purged within 60 days.';

  @override
  String get legalDataConsentRetentionHeading => '10. Training data retention';

  @override
  String get legalDataConsentTitle => 'Data & AI Consent Policy';

  @override
  String get legalDataConsentWhatIsTrainingBody =>
      'AI training in this context means using your data — after anonymization and pseudonymization — to improve the accuracy, relevance, or safety of AI models that power Umbrella features. It does not mean sharing identifiable client data with any third party. Training pipelines are operated by DVTech Ventures or its contracted AI providers under data-processing agreements.';

  @override
  String get legalDataConsentWhatIsTrainingHeading =>
      '2. What AI training means';

  @override
  String get legalDataConsentWithdrawBody =>
      'You may withdraw your consent at any time via account settings or by emailing support@odaflow.com. Upon withdrawal: (a) no further data from your account will enter any training pipeline; (b) previously anonymized data that has already been incorporated into a trained model cannot be removed from that model (as is technically infeasible with anonymized aggregate data, consistent with GDPR Recital 26); (c) any pending training batches containing your data will be purged within 30 days; (d) you will receive confirmation of withdrawal by email within 5 business days.';

  @override
  String get legalDataConsentWithdrawHeading => '8. Withdrawal of consent';

