  @override
  String get legalDisclaimerAINotLawyerBody =>
      'Umbrella\'s AI systems are large language models trained on general legal corpora. They do not hold practising certificates, cannot appear in court, are not regulated by any bar association or law society, and owe no duty of care to you as a lawyer would. AI Outputs may: contain factual errors or hallucinations; omit material considerations relevant to your specific facts; cite statutes or cases that have been amended, repealed, or overruled; fail to account for recent legislative changes; and misinterpret complex or ambiguous legal questions. You must treat every AI Output as a starting point for inquiry, not a final answer.';

  @override
  String get legalDisclaimerAINotLawyerHeading => '3. AI is not a lawyer';

  @override
  String get legalDisclaimerCitationBody =>
      'When Umbrella cites a statute, regulation, rule, or judicial decision, you must independently verify: (a) that the cited source exists; (b) that the citation is accurate (section, subsection, and year); (c) that the source is currently in force and has not been amended or repealed; (d) that the quoted text accurately reflects the source. AI citation errors — including fabricated citations — are a known limitation of all current AI systems. Never rely on a citation in legal proceedings, advice, or filings without independent verification.';

  @override
  String get legalDisclaimerCitationHeading => '4. Citation accuracy';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'India: AI analysis is based on central legislation, state acts where specified, and published judicial decisions. It does not account for district court-level practice, local bar customs, or uncodified procedural rules. United States: AI analysis is based on federal law and selected state law. US legal analysis is not a substitute for state-specific licensed counsel. Not available for immigration, criminal defence, or tax matters without verified lawyer review. Kenya: analysis draws on Kenyan statutes, subsidiary legislation, and published High Court and Court of Appeal decisions. It does not account for customary law, magistrate court variations, or unpublished rulings. United Kingdom: analysis covers English and Welsh law. Scots law, Northern Irish law, and devolved matters may differ significantly; seek jurisdiction-specific advice.';

  @override
  String get legalDisclaimerJurisdictionHeading =>
      '8. Jurisdictional limitations';

  @override
  String get legalDisclaimerLawyerReviewBody =>
      'Certain Umbrella outputs carry an \"Attorney Reviewed\" badge, indicating that a licensed lawyer on our marketplace has reviewed and approved the content. Even reviewed outputs: (a) reflect the lawyer\'s opinion at the time of review; (b) do not constitute a formal legal opinion unless accompanied by a signed opinion letter; (c) do not create an attorney-client relationship unless a separate retainer agreement is executed; (d) may become outdated as law changes. The reviewing lawyer is an independent contractor; DVTech Ventures does not guarantee the quality or accuracy of any reviewed output.';

  @override
  String get legalDisclaimerLawyerReviewHeading => '7. Lawyer-reviewed outputs';

  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'Communications with Umbrella\'s AI are not protected by attorney-client privilege or legal professional privilege in any jurisdiction. Do not submit information to the platform that you intend to protect under privilege. If you engage a licensed lawyer through the Umbrella marketplace, privilege may attach to your communications with that lawyer under an executed retainer agreement, but not to your prior AI interactions.';

  @override
  String get legalDisclaimerNoPrivilegeHeading =>
      '5. No attorney-client privilege';

  @override
  String get legalDisclaimerNotProvideAdvice =>
      'Guaranteed legal advice or predicted legal outcomes';

  @override
  String get legalDisclaimerNotProvideHeading => '11. What we do not provide';

  @override
  String get legalDisclaimerNotProvidePrivilege =>
      'Attorney-client privilege for AI interactions';

  @override
  String get legalDisclaimerNotProvideProfessional =>
      'Professional indemnity for AI-generated outputs';

  @override
  String get legalDisclaimerNotProvideRepresentation =>
      'Representation before courts, tribunals, or regulatory bodies';

  @override
  String get legalDisclaimerNotProvideSubstitute =>
      'A substitute for a licensed, qualified lawyer in your jurisdiction';

  @override
  String get legalDisclaimerPageDescription =>
      'Important notices about Umbrella\'s AI-generated legal information, its limitations, and user responsibilities. This disclaimer applies to all products and features offered by DVTech Ventures through the Umbrella platform.';

  @override
  String get legalDisclaimerPageTitle => 'Legal Disclaimer';

  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech Ventures is a technology company, not a regulated legal services provider. We are not authorised by the Solicitors Regulation Authority (UK), the Bar Council of India, the Law Society of Kenya, any US state bar, or any other legal regulatory body to provide legal services. The Umbrella platform does not provide regulated legal activity as defined in the Legal Services Act 2007 (UK) or equivalent legislation in other jurisdictions.';

  @override
  String get legalDisclaimerRegulatoryHeading => '9. Regulatory status';

  @override
  String get legalDisclaimerRelianceBody =>
      'You acknowledge that: (a) you will not rely solely on AI Outputs to make decisions that affect your legal rights or obligations; (b) you will seek independent qualified legal advice before commencing, defending, or settling legal proceedings; (c) DVTech Ventures is not liable for any harm arising from your reliance on AI Outputs without independent verification. This limitation applies to the fullest extent permitted by applicable law.';

  @override
  String get legalDisclaimerRelianceHeading => '6. Limitation on reliance';

