  String get legalPrivacyLegalBasisBody =>
      'We process personal data under the following legal bases depending on your jurisdiction: (a) Contract — processing necessary to deliver services you have signed up for; (b) Legitimate interests — fraud prevention, platform security, product improvement; (c) Consent — AI training, marketing emails, cookies beyond strictly necessary; (d) Legal obligation — compliance with applicable law. For India, processing is governed by the Digital Personal Data Protection Act 2023 (DPDP Act). For the UK/EU, processing complies with the UK GDPR and EU GDPR. For Kenya, processing complies with the Data Protection Act 2019. For US users, we comply with applicable state privacy laws including the CCPA/CPRA.';

